from janetcode_tools import glob, read_file
import re

# Get all Go files in src/
go_files = glob(pattern="*.go", path="src")
print(f"Found {len(go_files.splitlines())} Go files\n")

results = []
retry_budget_info = []

# Process each file
for file_path in sorted(go_files.splitlines()):
    if not file_path.strip():
        continue

    full_path = f"src/{file_path}"
    content = read_file(path=full_path)

    # Count top-level func declarations
    # We need to count lines that start with "func " (not indented, not inside other blocks)
    func_count = 0
    for line in content.splitlines():
        # Strip line numbers added by read_file
        line_text = line.split(':', 1)[1] if ':' in line else line
        # Check if line starts with "func " (top-level)
        if re.match(r'^func\s+', line_text.strip()) and not line_text.startswith('\t') and not line_text.startswith(' '):
            func_count += 1

    results.append({
        'file': file_path,
        'func_count': func_count
    })

    # Check for RetryBudget declaration
    for line in content.splitlines():
        line_text = line.split(':', 1)[1] if ':' in line else line
        # Look for variable declarations with RetryBudget
        if 'RetryBudget' in line_text and ('var ' in line_text or 'const ' in line_text or '=' in line_text):
            retry_budget_info.append({
                'file': file_path,
                'line': line_text.strip()
            })

# Print results
print("=== Function Counts ===")
for r in results:
    print(f"{r['file']}: {r['func_count']} top-level func declarations")

print("\n=== RetryBudget Declarations ===")
if retry_budget_info:
    for info in retry_budget_info:
        print(f"{info['file']}: {info['line']}")
else:
    print("No RetryBudget declarations found")

