from janetcode_tools import glob, read_file, plain
import re

# Get all Go files in src/
go_files = glob(pattern="*.go", path="src")

results = []
retry_budget_info = []

# Process each file
for file_path in sorted(go_files.splitlines()):
    if not file_path.strip():
        continue

    full_path = f"src/{file_path}"
    content = read_file(path=full_path)

    # Remove line numbers to get plain text
    plain_content = plain(content)

    # Count top-level func declarations
    func_count = 0
    for line in plain_content.splitlines():
        # Check if line starts with "func " (top-level, not method)
        if re.match(r'^func\s+[A-Z]', line):
            func_count += 1

    results.append({
        'file': file_path,
        'func_count': func_count
    })

    # Check for RetryBudget declaration
    for line in plain_content.splitlines():
        # Look for RetryBudget constant/variable declaration
        if re.match(r'^\s*(const|var)\s+RetryBudget', line):
            # Extract the value
            match = re.search(r'=\s*(\d+)', line)
            value = match.group(1) if match else "unknown"
            retry_budget_info.append({
                'file': file_path,
                'value': value
            })
            break

# Print results
print("=== Function Counts per File ===")
for r in results:
    print(f"  {r['file']}: {r['func_count']} func declarations")

print("\n=== RetryBudget Declarations ===")
if retry_budget_info:
    for info in retry_budget_info:
        print(f"  {info['file']}: RetryBudget = {info['value']}")
else:
    print("  None found")

